define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_16.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e85894","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_12.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e85998","topics":[]},{"title":"Adjusting the static pressure on the compressor","shortdesc":"<p class=\"shortdesc\">When both the static and dynamic compressor pressures are out of range, adjust the static pressure.<\/p>","href":"t_AdjustingTheStaticPressureOnTheCompressor.html","attributes":{"data-id":"id_2012445"},"menu":{"hasChildren":false},"tocID":"id_2012445-d46e86102","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_12.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e86206","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_21.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e86310","topics":[]}]});